// Baselines are generated by this detector against the production registrar
// (registerAPIRoutes) with optional handlers enabled and test mode off.
//
// Issue keys on the missing-route baseline: 249 is the phantom export/import
// set, 250 is the notification paths the UI calls that are not registered,
// 363 is GET /api/v1/version. App.vue and BackupManagementPage call /version;
// the axios client joins that with base URL /api/v1, while the server
// registers GET /version on the root router. The detector finds no
// precedence mismatch, literal or parameterized, so precedence.json is an
// empty list. A new mismatch, or a baseline entry whose pair is no longer
// missing, fails the test.

func TestRouteContract(t *testing.T) {
	t.Setenv("SHELLY_SECURITY_VALIDATION_TEST_MODE", "")
	if os.Getenv("SHELLY_SECURITY_VALIDATION_TEST_MODE") == "true" {
		t.Fatal("test mode still enabled; the production registrar would be skipped")
	}

	root := routeContractRoot(t)
	calls, errs := extractRouteContract(root)
	if len(errs) > 0 {
		t.Fatalf("extractor failed closed:\n%s", joinRouteContractErrs(errs))
	}
	assertKnownRouteBypasses(t, root, calls)

	router := newRouteContractRouter(t)
	req, err := http.NewRequest(http.MethodGet, "/api/v1/devices", nil)
	require.NoError(t, err)
	var match mux.RouteMatch
	if !router.Match(req, &match) || match.MatchErr != nil || match.Route == nil {
		t.Fatal("GET /api/v1/devices did not match a route")
	}
	tmpl, err := match.Route.GetPathTemplate()
	require.NoError(t, err)
	if got := normalizeRouteTemplate(tmpl); got != "/api/v1/devices" {
		t.Fatalf("GET /api/v1/devices matched %q (normalized %s)", tmpl, got)
	}

	missing := missingRoutePairs(calls, routeTable(t, router))
	baseMissing := loadRouteBaseline[routeContractBaseline](t, root, "missing.json")
	err = checkRouteBaseline("missing", missing, baseMissing)
	if err != nil {
		t.Fatalf("%v\nextracted calls: %d\nactual missing:\n%s", err, len(calls), formatRoutePairs(missing))
	}

	prec, err := routePrecedence(router, calls)
	require.NoError(t, err)
	basePrec := loadRouteBaseline[routeContractPrecBaseline](t, root, "precedence.json")
	err = checkPrecBaseline(prec, basePrec)
	if err != nil {
		t.Fatalf("%v\nactual precedence:\n%s", err, formatRoutePrec(prec))
	}
}

func TestRouteContractFixtures(t *testing.T) {
	t.Run("wrong method", func(t *testing.T) {
		calls, errs := extractRouteContractSources(map[string]string{
			"ui/src/api/fixture.ts": "import api from './client'\nexport const f = () => api.get('/widgets')\n",
		}, nil)
		if len(errs) != 0 {
			t.Fatal(joinRouteContractErrs(errs))
		}
		if len(calls) != 1 || calls[0].Method != "GET" || calls[0].Template != "/api/v1/widgets" {
			t.Fatalf("calls: %+v", calls)
		}
		router := mux.NewRouter()
		router.HandleFunc("/api/v1/widgets", routeContractNop).Methods("POST")
		missing := missingRoutePairs(calls, routeTable(t, router))
		if len(missing) != 1 || missing[0].Method != "GET" || missing[0].Template != "/api/v1/widgets" {
			t.Fatalf("missing: %+v", missing)
		}
		prec, err := routePrecedence(router, calls)
		require.NoError(t, err)
		if len(prec) != 0 {
			t.Fatalf("wrong method was reported as precedence: %+v", prec)
		}
	})

	t.Run("precedence shadow", func(t *testing.T) {
		calls, errs := extractRouteContractSources(map[string]string{
			"ui/src/api/fixture.ts": "import api from './client'\nexport const f = () => api.get('/export/gitops')\n",
		}, nil)
		if len(errs) != 0 {
			t.Fatal(joinRouteContractErrs(errs))
		}
		router := mux.NewRouter()
		router.HandleFunc("/api/v1/export/{id}", routeContractNop).Methods("GET")
		router.HandleFunc("/api/v1/export/gitops", routeContractNop).Methods("POST")
		prec, err := routePrecedence(router, calls)
		require.NoError(t, err)
		if len(prec) != 1 || prec[0].Method != "GET" || prec[0].Request != "/api/v1/export/gitops" || prec[0].Matched != "/api/v1/export/{param}" {
			t.Fatalf("precedence: %+v", prec)
		}
		missing := missingRoutePairs(calls, routeTable(t, router))
		if len(missing) != 1 || missing[0].Template != "/api/v1/export/gitops" {
			t.Fatalf("shadowed GET must still be a missing exact pair: %+v", missing)
		}
	})

	t.Run("unrecognized call", func(t *testing.T) {
		_, errs := extractRouteContractSources(map[string]string{
			"ui/src/fixture.ts": "export const f = () => fetch('/nope')\n",
		}, nil)
		if len(errs) != 1 || !strings.Contains(errs[0].Error(), "ui/src/fixture.ts:1:") {
			t.Fatalf("errs: %+v", errs)
		}
		_, errs = extractRouteContractSources(map[string]string{
			"ui/src/api/fixture.ts": "import api from './client'\nconst url = '/version'\napi.get(url)\n",
		}, nil)
		if len(errs) != 1 || !strings.Contains(errs[0].Error(), "ui/src/api/fixture.ts:3:") {
			t.Fatalf("errs: %+v", errs)
		}
	})

	t.Run("url expression after the literal", func(t *testing.T) {
		for name, call := range map[string]string{
			"concat":   "api.get('/devices' + '/not-a-route')",
			"template": "api.get(`/devices/${id}` + suffix)",
			"method":   "api.get('/devices'.concat(suffix))",
		} {
			src := "import api from './client'\nexport const f = (id: string, suffix: string) =>\n  " + call + "\n"
			calls, errs := extractRouteContractSources(map[string]string{"ui/src/api/fixture.ts": src}, nil)
			if len(errs) != 1 || !strings.Contains(errs[0].Error(), "ui/src/api/fixture.ts:3:") {
				t.Fatalf("%s: calls %+v errs: %+v", name, calls, errs)
			}
		}
	})

	t.Run("other uses of the client binding", func(t *testing.T) {
		for name, tc := range map[string]struct {
			body string
			line int
		}{
			"called directly":  {"api({ method: 'GET', url: '/missing' })", 2},
			"computed member":  {"api['get']('/missing')", 2},
			"aliased":          {"const c = api\nc.get(u)", 2},
			"passed as value":  {"wrap(api)", 2},
			"non-http member":  {"api.interceptors.request.use(f)", 2},
			"shorthand object": {"export default { api }", 2},
		} {
			src := "import api from './client'\n" + tc.body + "\n"
			calls, errs := extractRouteContractSources(map[string]string{"ui/src/api/fixture.ts": src}, nil)
			want := fmt.Sprintf("ui/src/api/fixture.ts:%d:", tc.line)
			if len(errs) != 1 || !strings.Contains(errs[0].Error(), want) {
				t.Fatalf("%s: calls %+v errs: %+v", name, calls, errs)
			}
		}
		// A property of another object that happens to be named api is not the binding.
		calls, errs := extractRouteContractSources(map[string]string{
			"ui/src/api/fixture.ts": "import api from './client'\nconst x = cfg.api\nconst y = cfg?.api\nexport const f = () => api.get('/ok')\n",
		}, nil)
		if len(errs) != 0 || len(calls) != 1 {
			t.Fatalf("calls %+v errs: %s", calls, joinRouteContractErrs(errs))
		}
	})

	t.Run("parameterized precedence shadow", func(t *testing.T) {
		calls, errs := extractRouteContractSources(map[string]string{
			"ui/src/api/fixture.ts": "import api from './client'\n" +
				"export const f = (id: string) => api.get(`/devices/${id}/config/current`)\n" +
				"export const g = (id: string) => api.get(`/export/${id}`)\n",
		}, nil)
		if len(errs) != 0 {
			t.Fatal(joinRouteContractErrs(errs))
		}
		const uuid = `[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}`
		router := mux.NewRouter()
		router.HandleFunc("/api/v1/devices/{id}/config/{section}", routeContractNop).Methods("GET")
		router.HandleFunc("/api/v1/devices/{id}/config/current", routeContractNop).Methods("GET")
		router.HandleFunc("/api/v1/export/{id:"+uuid+"}", routeContractNop).Methods("GET")
		prec, err := routePrecedence(router, calls)
		require.NoError(t, err)
		if len(prec) != 1 || prec[0].Request != "/api/v1/devices/{param}/config/current" ||
			prec[0].Matched != "/api/v1/devices/{param}/config/{param}" {
			t.Fatalf("precedence: %+v", prec)
		}
	})

	t.Run("mixed parameter constraints", func(t *testing.T) {
		calls, errs := extractRouteContractSources(map[string]string{
			"ui/src/api/fixture.ts": "import api from './client'\n" +
				"export const f = (id: number, s: string) => api.get(`/devices/${id}/config/${s}`)\n",
		}, nil)
		if len(errs) != 0 {
			t.Fatal(joinRouteContractErrs(errs))
		}
		router := mux.NewRouter()
		router.HandleFunc("/api/v1/devices/{id:[0-9]+}/config/{section:[a-z]+}", routeContractNop).Methods("GET")
		prec, err := routePrecedence(router, calls)
		require.NoError(t, err)
		if len(prec) != 0 {
			t.Fatalf("precedence: %+v", prec)
		}
		// The same call is still checked for shadowing by an earlier route.
		router = mux.NewRouter()
		router.HandleFunc("/api/v1/devices/{id:[0-9]+}/{kind}/{name}", routeContractNop).Methods("GET")
		router.HandleFunc("/api/v1/devices/{id:[0-9]+}/config/{section:[a-z]+}", routeContractNop).Methods("GET")
		prec, err = routePrecedence(router, calls)
		require.NoError(t, err)
		if len(prec) != 1 || prec[0].Matched != "/api/v1/devices/{param}/{param}/{param}" {
			t.Fatalf("precedence: %+v", prec)
		}
	})

	t.Run("comments strings regex and division", func(t *testing.T) {
		src := "import api from './client'\n" +
			"// fetch('/hidden')\n" +
			"const s = \"fetch('/hidden')\"\n" +
			"const re = /fetch\\('\\/x'\\)/\n" +
			"const n = 1 / 2\n" +
			"export const f = () => api.get('/after')\n"
		calls, errs := extractRouteContractSources(map[string]string{"ui/src/api/fixture.ts": src}, nil)
		if len(errs) != 0 {
			t.Fatal(joinRouteContractErrs(errs))
		}
		if len(calls) != 1 || calls[0].Template != "/api/v1/after" || calls[0].Line != 6 {
			t.Fatalf("calls: %+v", calls)
		}
	})

	t.Run("multiline generic template", func(t *testing.T) {
		src := "import api from './client'\n" +
			"export async function f(params: { deviceId: string; templateId: string }) {\n" +
			"  return api.post<APIResponse<{ templates: ConfigTemplate[] }>>(\n" +
			"    `/devices/${params.deviceId}/templates/new/${params.templateId}`,\n" +
			"    null,\n" +
			"  )\n" +
			"}\n"
		calls, errs := extractRouteContractSources(map[string]string{"ui/src/api/fixture.ts": src}, nil)
		if len(errs) != 0 {
			t.Fatal(joinRouteContractErrs(errs))
		}
		if len(calls) != 1 || calls[0].Method != "POST" || calls[0].Template != "/api/v1/devices/{param}/templates/new/{param}" || calls[0].Line != 3 {
			t.Fatalf("calls: %+v", calls)
		}
	})

	t.Run("vue script line", func(t *testing.T) {
		src := "<template><div/></template>\n" +
			"<script setup lang=\"ts\">\n" +
			"import api from '@/api/client'\n" +
			"export const load = () => api.get('/version')\n" +
			"</script>\n"
		calls, errs := extractRouteContractSources(map[string]string{"ui/src/App.vue": src}, nil)
		if len(errs) != 0 {
			t.Fatal(joinRouteContractErrs(errs))
		}
		if len(calls) != 1 || calls[0].Line != 4 || calls[0].Template != "/api/v1/version" {
			t.Fatalf("calls: %+v", calls)
		}
	})

	t.Run("stale manifest", func(t *testing.T) {
		src := "const ws = new WebSocket(url)\n"
		_, errs := extractRouteContractSources(map[string]string{"ui/src/api/ws.ts": src}, []routeContractManifest{{
			File: "ui/src/api/ws.ts", Line: 99, Kind: "new-websocket", Method: "GET", Template: "/metrics/ws",
		}})
		text := joinRouteContractErrs(errs)
		if !strings.Contains(text, "ui/src/api/ws.ts:1:") || !strings.Contains(text, "not in manifest") {
			t.Fatalf("missing unsupported transport: %s", text)
		}
		if !strings.Contains(text, "ui/src/api/ws.ts:99:") || !strings.Contains(text, "stale") {
			t.Fatalf("missing stale manifest: %s", text)
		}
	})

	t.Run("escapes in paths", func(t *testing.T) {
		src := "import api from './client'\n" +
			"export const f = () => api.get('/w\\u0069dgets')\n" +
			"export const g = () => api.get('\\x2fw')\n"
		calls, errs := extractRouteContractSources(map[string]string{"ui/src/api/fixture.ts": src}, nil)
		if len(errs) != 0 {
			t.Fatal(joinRouteContractErrs(errs))
		}
		if len(calls) != 2 || calls[0].Template != "/api/v1/widgets" || calls[1].Template != "/api/v1/w" {
			t.Fatalf("calls: %+v", calls)
		}
	})

	t.Run("indirect fetch", func(t *testing.T) {
		for name, body := range map[string]string{
			"aliased":       "const request = fetch\nrequest('/missing')",
			"call":          "fetch.call(null, '/missing')",
			"passed on":     "wrap(fetch)",
			"window member": "window.fetch('/missing')",
			"global xhr":    "new globalThis.XMLHttpRequest()",
		} {
			calls, errs := extractRouteContractSources(map[string]string{"ui/src/fixture.ts": body + "\n"}, nil)
			if len(errs) != 1 || !strings.Contains(errs[0].Error(), "ui/src/fixture.ts:1:") {
				t.Fatalf("%s: calls %+v errs: %+v", name, calls, errs)
			}
		}
		// A property named fetch belongs to another object.
		calls, errs := extractRouteContractSources(map[string]string{
			"ui/src/fixture.ts": "export const f = (store: any) => store.fetch()\n",
		}, nil)
		if len(errs) != 0 || len(calls) != 0 {
			t.Fatalf("calls %+v errs: %s", calls, joinRouteContractErrs(errs))
		}
	})

	t.Run("request config", func(t *testing.T) {
		for name, call := range map[string]string{
			"baseURL key":        "api.get('/x', { baseURL: '/unserved' })",
			"quoted baseURL key": "api.get('/x', { 'baseURL': '/unserved' })",
			"shorthand baseURL":  "api.get('/x', { baseURL })",
			"nested baseURL":     "api.get('/x', { params: { baseURL: 1 } })",
			"post config":        "api.post('/x', body, { baseURL: '/unserved' })",
			"config variable":    "api.get('/x', cfg)",
			"config spread":      "api.get('/x', { ...cfg })",
			"computed key":       "api.get('/x', { [k]: v })",
		} {
			src := "import api from './client'\n" + call + "\n"
			calls, errs := extractRouteContractSources(map[string]string{"ui/src/api/fixture.ts": src}, nil)
			if len(errs) != 1 || !strings.Contains(errs[0].Error(), "ui/src/api/fixture.ts:2:") {
				t.Fatalf("%s: calls %+v errs: %+v", name, calls, errs)
			}
		}
		src := "import api from './client'\n" +
			"export const a = () => api.get('/a', { params: { page: [1, 2] }, responseType: 'blob' })\n" +
			"export const b = (data: any) => api.post('/b', data)\n" +
			"export const c = (data: any) => api.post('/c', { ...data }, { timeout: 1 })\n" +
			"export const d = () => api.get('/d',)\n" +
			"export const e = () => api.put('/e', [`${1}`, f(2)], { headers: { 'X-A': '1' } })\n"
		calls, errs := extractRouteContractSources(map[string]string{"ui/src/api/fixture.ts": src}, nil)
		if len(errs) != 0 || len(calls) != 5 {
			t.Fatalf("calls %+v errs: %s", calls, joinRouteContractErrs(errs))
		}
	})

	t.Run("client module instance", func(t *testing.T) {
		const head = "import axios from 'axios'\n" +
			"export const api = axios.create({ baseURL: '/api/v1' })\n"
		for name, body := range map[string]string{
			"http method":     "api.get('/missing')",
			"request":         "api.request({ url: '/missing' })",
			"called directly": "api({ url: '/missing' })",
			"aliased":         "const c = api",
			"axios called":    "axios('/missing')",
		} {
			src := head + body + "\n"
			calls, errs := extractRouteContractSources(map[string]string{"ui/src/api/client.ts": src}, nil)
			if len(errs) != 1 || !strings.Contains(errs[0].Error(), "ui/src/api/client.ts:3:") {
				t.Fatalf("%s: calls %+v errs: %+v", name, calls, errs)
			}
		}
		_, errs := extractRouteContractSources(map[string]string{
			"ui/src/api/client.ts": "import axios from 'axios'\nexport default axios.create({ baseURL: '/api/v1' })\n",
		}, nil)
		if len(errs) != 1 || !strings.Contains(errs[0].Error(), "ui/src/api/client.ts:2:") {
			t.Fatalf("unbound create: %+v", errs)
		}
	})

	t.Run("re-export of the client", func(t *testing.T) {
		for name, body := range map[string]string{
			"named default": "export { default as api } from './client'",
			"named":         "export { api } from '@/api/client'",
			"star":          "export * from './client'",
			"star as":       "export * as http from './client'",
			"axios":         "export { default } from 'axios'",
		} {
			calls, errs := extractRouteContractSources(map[string]string{"ui/src/api/index.ts": body + "\n"}, nil)
			if len(errs) != 1 || !strings.Contains(errs[0].Error(), "ui/src/api/index.ts:1:") {
				t.Fatalf("%s: calls %+v errs: %+v", name, calls, errs)
			}
		}
		src := "export type { Device } from './client'\n" +
			"export { listDevices } from './devices'\n" +
			"export * from './types'\n" +
			"export const x = 1\n"
		calls, errs := extractRouteContractSources(map[string]string{"ui/src/api/index.ts": src}, nil)
		if len(errs) != 0 || len(calls) != 0 {
			t.Fatalf("calls %+v errs: %s", calls, joinRouteContractErrs(errs))
		}
	})

	t.Run("client base path", func(t *testing.T) {
		for name, tc := range map[string]struct {
			src  string
			line int
		}{
			"other default": {"import axios from 'axios'\n\nexport const api = axios.create({ baseURL: env.X || '/api/v2' })\n", 3},
			"no fallback":   {"import axios from 'axios'\nexport const api = axios.create({ baseURL: env.X })\n", 2},
			"none":          {"import axios from 'axios'\nexport const api = axios.create({})\n", 1},
			"two":           {"import axios from 'axios'\nexport const api = axios.create({ baseURL: '/api/v1' })\nconst baseURL = 1\n", 1},
		} {
			_, errs := extractRouteContractSources(map[string]string{"ui/src/api/client.ts": tc.src}, nil)
			want := fmt.Sprintf("ui/src/api/client.ts:%d:", tc.line)
			if len(errs) != 1 || !strings.Contains(errs[0].Error(), want) {
				t.Fatalf("%s: errs: %+v", name, errs)
			}
		}
		// A comment does not count as the base.
		_, errs := extractRouteContractSources(map[string]string{
			"ui/src/api/client.ts": "import axios from 'axios'\n// baseURL: '/api/v2'\nexport const api = axios.create({ baseURL: e || \"/api/v1\" })\n",
		}, nil)
		if len(errs) != 0 {
			t.Fatal(joinRouteContractErrs(errs))
		}

		root := t.TempDir()
		require.NoError(t, os.MkdirAll(filepath.Join(root, "ui", "src", "api"), 0o755))
		require.NoError(t, os.MkdirAll(filepath.Join(root, "internal", "api", "testdata", "routecontract"), 0o755))
		require.NoError(t, os.WriteFile(filepath.Join(root, "internal", "api", "testdata", "routecontract", "transports.json"), []byte("[]\n"), 0o600))
		require.NoError(t, os.WriteFile(filepath.Join(root, "ui", "src", "api", "devices.ts"), []byte("export {}\n"), 0o600))
		_, errs = extractRouteContract(root)
		if len(errs) != 1 || !strings.Contains(errs[0].Error(), "ui/src/api/client.ts:1:") {
			t.Fatalf("missing client module: %+v", errs)
		}
	})

	t.Run("client module is not a route", func(t *testing.T) {
		src := "import axios from 'axios'\n" +
			"const env: any = (import.meta as any)?.env || {}\n" +
			"export const api = axios.create({ baseURL: env.VITE_API_BASE || '/api/v1' })\n"
		calls, errs := extractRouteContractSources(map[string]string{"ui/src/api/client.ts": src}, nil)
		if len(errs) != 0 {
			t.Fatal(joinRouteContractErrs(errs))
		}
		if len(calls) != 0 {
			t.Fatalf("calls: %+v", calls)
		}
	})
}

func TestRouteContractFilesRejectsUnscannedCode(t *testing.T) {
	for _, name := range []string{"legacy.js", "legacy.mjs", "legacy.cjs", "Widget.jsx"} {
		root := t.TempDir()
		dir := filepath.Join(root, "ui", "src", "api")
		require.NoError(t, os.MkdirAll(dir, 0o755))
		require.NoError(t, os.WriteFile(filepath.Join(dir, name), []byte("export {}\n"), 0o600))
		_, err := routeContractFiles(root)
		if err == nil || !strings.Contains(err.Error(), "ui/src/api/"+name) {
			t.Fatalf("%s: err %v", name, err)
		}
	}
}

func TestRouteContractBaselineRules(t *testing.T) {
	err := checkRouteBaseline("missing", nil, []routeContractBaseline{{
		Method: "GET", Template: "/api/v1/gone", Issue: 249,
	}})
	if err == nil || !strings.Contains(err.Error(), "stale") {
		t.Fatalf("err: %v", err)
	}
	err = checkRouteBaseline("missing", []routeContractPair{{Method: "GET", Template: "/api/v1/missing"}}, nil)
	if err == nil || !strings.Contains(err.Error(), "missing from missing baseline") {
		t.Fatalf("err: %v", err)
	}
	err = checkRouteBaseline("missing", []routeContractPair{{Method: "GET", Template: "/api/v1/missing"}}, []routeContractBaseline{{
		Method: "GET", Template: "/api/v1/missing", Issue: 0,
	}})
	if err == nil || !strings.Contains(err.Error(), "no issue") {
		t.Fatalf("err: %v", err)
	}
}

func TestNormalizeRouteTemplateCollapsesMuxRegexp(t *testing.T) {
	const exportIDPattern = `[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}`
	got := normalizeRouteTemplate("/api/v1/export/{id:" + exportIDPattern + "}")
	if got != "/api/v1/export/{param}" {
		t.Fatal(got)
	}
	if normalizeRouteTemplate("/api/v1/devices/{id}/config/{name}") != "/api/v1/devices/{param}/config/{param}" {
		t.Fatal(normalizeRouteTemplate("/api/v1/devices/{id}/config/{name}"))
	}
}

