func newRouteContractRouter(t *testing.T) *mux.Router {
	t.Helper()
	db, cleanup := testutil.TestDatabase(t)
	t.Cleanup(cleanup)

	logger, err := logging.New(logging.Config{Level: "error", Format: "text"})
	require.NoError(t, err)

	msvc := metrics.NewService(db.GetDB(), logger, prometheus.NewRegistry())
	mhandler := metrics.NewHandler(msvc, logger)
	engine := sync.NewSyncEngine(db, logger)
	require.NoError(t, engine.RegisterPlugin(&mockSyncPlugin{}))

	h := NewHandlerWithLogger(db, nil, testNotificationHandler(t, db), mhandler, logger)
	h.ExportHandlers = NewSyncHandlers(engine, logger)
	h.ImportHandlers = NewImportHandlers(engine, logger)
	router := SetupRoutesWithSecurity(h, logger, middleware.DefaultSecurityConfig(), middleware.DefaultValidationConfig())
	// The production router starts the monitor's alert and cleanup goroutines.
	sm, ok := h.securityMonitor.(*middleware.SecurityMonitor)
	require.True(t, ok, "production router did not build a security monitor")
	t.Cleanup(sm.Close)
	return router
}

func routeContractRoot(t *testing.T) string {
	t.Helper()
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("runtime.Caller failed")
	}
	root := filepath.Dir(filepath.Dir(filepath.Dir(file)))
	if _, err := os.Stat(filepath.Join(root, "go.mod")); err != nil {
		t.Fatalf("repo root %s: %v", root, err)
	}
	return root
}

func loadRouteBaseline[T any](t *testing.T, root, name string) []T {
	t.Helper()
	body, err := os.ReadFile(filepath.Join(root, "internal", "api", "testdata", "routecontract", name))
	require.NoError(t, err)
	var out []T
	require.NoError(t, json.Unmarshal(body, &out))
	return out
}

func assertKnownRouteBypasses(t *testing.T, root string, calls []routeContractCall) {
	t.Helper()
	want := []struct {
		file, method, tmpl, needle string
		min                        int
	}{
		{"ui/src/App.vue", "GET", "/api/v1/version", "api.get", 1},
		{"ui/src/pages/BackupManagementPage.vue", "GET", "/api/v1/export/history", "api.get", 3},
		{"ui/src/pages/BackupManagementPage.vue", "GET", "/api/v1/devices", "api.get", 1},
		{"ui/src/pages/BackupManagementPage.vue", "GET", "/api/v1/version", "api.get", 1},
		{"ui/src/api/metrics.ts", "GET", "/metrics/ws", "new WebSocket", 1},
		{"ui/src/stores/metrics.ts", "GET", "/metrics/ws", "useWebSocket", 1},
	}
	for _, w := range want {
		n := 0
		for _, call := range calls {
			if call.File != w.file || call.Method != w.method || call.Template != w.tmpl {
				continue
			}
			n++
			line := routeSourceLine(t, root, call.File, call.Line)
			if !strings.Contains(line, w.needle) {
				t.Fatalf("%s:%d reported as %s %s but the source line is %q", call.File, call.Line, call.Method, call.Template, line)
			}
		}
		if n < w.min {
			t.Fatalf("extractor missed %s %s %s: found %d want >= %d", w.file, w.method, w.tmpl, n, w.min)
		}
	}
	for _, call := range calls {
		if call.File == "ui/src/composables/useWebSocket.ts" {
			t.Fatalf("generic websocket helper emitted a route: %+v", call)
		}
	}
}

func routeSourceLine(t *testing.T, root, rel string, line int) string {
	t.Helper()
	body, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(rel)))
	require.NoError(t, err)
	lines := strings.Split(string(body), "\n")
	if line < 1 || line > len(lines) {
		t.Fatalf("%s:%d out of range (%d lines)", rel, line, len(lines))
	}
	return lines[line-1]
}

func joinRouteContractErrs(errs []routeContractError) string {
	parts := make([]string, len(errs))
	for i, err := range errs {
		parts[i] = err.Error()
	}
	return strings.Join(parts, "\n")
}

func formatRoutePairs(pairs []routeContractPair) string {
	if len(pairs) == 0 {
		return "(none)"
	}
	lines := make([]string, len(pairs))
	for i, pair := range pairs {
		lines[i] = pair.Method + " " + pair.Template
	}
	return strings.Join(lines, "\n")
}

func formatRoutePrec(items []routeContractPrec) string {
	if len(items) == 0 {
		return "(none)"
	}
	lines := make([]string, len(items))
	for i, item := range items {
		lines[i] = item.Method + " " + item.Request + " => " + item.Matched
	}
	return strings.Join(lines, "\n")
}
